import os
import json
import time
import requests
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('ci-access')
GITHUB_API = 'https://api.github.com'
HEADERS = {'Authorization': f"Bearer {os.environ['GITHUB_TOKEN']}", 'Accept': 'application/vnd.github+json'}
AUDIT_LOG = os.environ.get('REVOCATION_AUDIT_LOG', 'revocations.jsonl')

def _delete_secret(repo: str, name: str) -> int:
    resp = requests.delete(f'{GITHUB_API}/repos/{repo}/actions/secrets/{name}', headers=HEADERS, timeout=15)
    if resp.status_code not in (204, 404):
        resp.raise_for_status()
    return resp.status_code

@mcp.tool()
def revoke_deploy_key_and_purge_secrets(repo: str, key_id: int, secret_names: list) -> dict:
    resp = requests.delete(f'{GITHUB_API}/repos/{repo}/keys/{key_id}', headers=HEADERS, timeout=15)
    if resp.status_code not in (204, 404):
        resp.raise_for_status()
    results = {}
    for name in secret_names:
        results[name] = _delete_secret(repo, name)
    entry = {'ts': int(time.time()), 'repo': repo, 'key_id': key_id, 'secrets': list(secret_names)}
    with open(AUDIT_LOG, 'a') as f:
        f.write(json.dumps(entry) + '\n')
    return {'repo': repo, 'key_id': key_id, 'key_status': resp.status_code, 'secrets': results}
